const logarithm = ax.plot(x => Math.log(x), { xRange: [Math.exp(-2), 4, 0.025], color: GREEN });
const mirror = new DashedLine({ start: ax.c2p(-2, -2), end: ax.c2p(4, 4), color: GRAY });
let a = 0.8;
const pHandle = new Dot({ point: ax.c2p(a, Math.exp(a)), radius: 0.13, color: BLUE });
const qHandle = new Dot({ point: ax.c2p(Math.exp(a), a), radius: 0.13, color: GREEN });
const connector = new DashedLine({ start: pHandle.getCenter(), end: qHandle.getCenter(), color: YELLOW });
const midpoint = new Dot({ point: ax.c2p(0, 0), radius: 0.045, color: YELLOW });
const title = new Text({ text: 'Inverse functions are mirror images', fontSize: 28, color: WHITE });
title.moveTo([0, 3.4, 0]);
const hint = new Text({ text: 'Drag either colored point · the coordinates swap', fontSize: 21, color: GRAY });
hint.moveTo([0, -3.4, 0]);
const expLabel = new MathTex({ latex: 'y=e^x', color: BLUE });
const logLabel = new MathTex({ latex: 'y=\\ln(x)', color: GREEN });
const mirrorLabel = new MathTex({ latex: 'y=x', color: GRAY });
await expLabel.waitForRender();
await logLabel.waitForRender();
await mirrorLabel.waitForRender();
expLabel.scale(0.75).moveTo([-4.65, 1.65, 0]);
logLabel.scale(0.75).moveTo([-4.65, 0.7, 0]);
mirrorLabel.scale(0.75).moveTo([-4.65, -0.25, 0]);
