pHeading.moveTo([4.55, 1.8, 0]);
const pReadout = new Text({ text: '', fontSize: 21, color: BLUE });
pReadout.moveTo([4.55, 1.35, 0]);
const qHeading = new Text({ text: 'Logarithm point', fontSize: 20, color: GREEN });
qHeading.moveTo([4.55, 0.35, 0]);
const qReadout = new Text({ text: '', fontSize: 21, color: GREEN });
qReadout.moveTo([4.55, -0.1, 0]);
const swapLabel = new Text({ text: '(x, y) → (y, x)', fontSize: 21, color: YELLOW });
swapLabel.moveTo([4.55, -1.1, 0]);
scene.add(ax, mirror, title, hint, expLabel, logLabel, mirrorLabel, pHeading, pReadout, qHeading, qReadout, swapLabel);
await scene.play(new AnimationGroup([new Create(exponential), new Create(logarithm)]));
scene.add(connector, midpoint, pHandle, qHandle);
function update() {
  const b = Math.exp(a);
  const p = ax.c2p(a, b);
  const q = ax.c2p(b, a);
  pHandle.moveTo(p);
  qHandle.moveTo(q);
  connector.setStart(p);
  connector.setEnd(q);
  midpoint.moveTo(ax.c2p((a + b) / 2, (a + b) / 2));
  pReadout.setText('(' + a.toFixed(2) + ', ' + b.toFixed(2) + ')');
  qReadout.setText('(' + b.toFixed(2) + ', ' + a.toFixed(2) + ')');
}
update();
const clamp = v => Math.max(-1.8, Math.min(Math.log(3.8), v));
makeDraggable(pHandle, scene, { onDrag: (mob, pos) => {
